<?php
header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/../Config/mikrotik.php';require_once __DIR__.'/../library/routeros_api.class.php';
try{$config=new MikroTikConfig();$router=$config->getRouter();if(!$router){echo json_encode(['status'=>'offline','message'=>'Router tidak tersedia']);exit;}$api=new RouterosAPI();$api->debug=false;if(!$api->connect($router['ip_address'],$router['username'],$router['password'],$router['api_port'])){echo json_encode(['status'=>'offline','message'=>'Router tidak dapat terhubung']);exit;}$items=$api->comm('/log/print');$api->disconnect();$rows=[];foreach(array_reverse($items) as $x){$rows[]=['time'=>$x['time']??'-','date'=>$x['date']??'','topics'=>$x['topics']??'-','message'=>$x['message']??'-'];}echo json_encode(['status'=>'online','router'=>$router['router_name'],'logs'=>array_slice($rows,0,300)]);}catch(Throwable $e){http_response_code(500);echo json_encode(['status'=>'error','message'=>$e->getMessage()]);}